WITH f AS (SELECT PGM_SYS_ID, FACILITY_NAME, CITY, STATE FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FACILITIES WHERE AIR_POLLUTANT_CLASS_CODE='MAJ' AND AIR_OPERATING_STATUS_CODE='OPR' AND NAICS_CODES LIKE '%311221%')
SELECT f.STATE, f.FACILITY_NAME, f.CITY, COUNT_IF(STATE_EPA_FLAG='S') FA_S, COUNT_IF(STATE_EPA_FLAG='E') FA_E, SUM(IFF(STATE_EPA_FLAG='S',PENALTY_AMOUNT,0)) PEN_S, SUM(IFF(STATE_EPA_FLAG='E',PENALTY_AMOUNT,0)) PEN_E, LISTAGG(DISTINCT IFF(STATE_EPA_FLAG='E',ENF_TYPE_DESC,NULL),'; ') EPA_TYPES
FROM f JOIN LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_ICIS_AIR_ICIS_AIR_FORMAL_ACTIONS x USING(PGM_SYS_ID) WHERE SETTLEMENT_ENTERED_DATE BETWEEN '2015-01-01' AND '2025-12-31' GROUP BY 1,2,3 ORDER BY 1,2
